import { useEffect, useRef, useState } from "react";

import { useIsDarkTheme, useThemeName } from "@/contexts/ThemeContext";

/**
 * What the mark is animating. Each mode is one playground state, all drawn
 * from the same 244 baked dots:
 *
 * - `thinking`: a breathing, turning sphere (the model is thinking).
 * - `working`: a thread wound into a torus knot (a tool is running).
 * - `searching`: a sphere swept by a lit meridian (a search tool is running).
 * - `waiting`: a breathing stack of rings (a person's answer is awaited).
 */
export type ActivityLogoMode = "thinking" | "working" | "searching" | "waiting";

export const ACTIVITY_LOGO_MODES: readonly ActivityLogoMode[] = [
  "thinking",
  "working",
  "searching",
  "waiting",
];

interface LogoPointSet {
  readonly n: number;
  /** Baked artwork positions, xyz per dot. */
  readonly p: Float32Array;
  /** Baked distance from the silhouette edge, one per dot. */
  readonly e: Float32Array;
}

interface Dot {
  x: number;
  y: number;
  z: number;
  r: number;
  /** Ink value: 0 = darkest ink on paper. Mirrored on dark themes. */
  white: number;
  a: number;
}

interface Rgb {
  r: number;
  g: number;
  b: number;
}

type Projector = (x: number, y: number, z: number) => [number, number, number];

const TURN = Math.PI * 2;

/**
 * The cycle every mode shares: dwell in the mode's own form, morph to the
 * mark, morph back. Shared timing keeps instances in phase, so the mark
 * assembles at the same moment when a row changes from one mode to another.
 */
const CYCLE = { dwell: 4.5, morph: 1.9, expo: 0.3, settle: 0.1 } as const;

/** Depth ink and radius scaling, common to every playground state. */
const INK = { inkFar: 0.6, inkSpan: 0.5, inkRim: 0.16, rsPow: 0.6, rMin: 0.3 } as const;

/** Playground tuning for `thinking`: a breathing sphere that becomes the mark. */
const THINKING = {
  turns: 1,
  tiltAmp: 0.34,
  churn: 0.09,
  sphereR: 0.92,
  flightFade: 0.25,
  haloShare: 0.12,
  haloOut: 0.18,
  haloZ: 0.8,
  haloRate: 0.9,
  haloR: 0.22,
  rBase: 0.55,
  rDepth: 1.5,
} as const;

/** Playground tuning for `working`: a thread wound into a (3, 2) torus knot. */
const WORKING = {
  lean: 0.4,
  yawAmp: 0.3,
  yawRate: 0.26,
  tilt: 0.4,
  wraps: 3,
  knotTurns: 2,
  major: 0.62,
  minor: 0.3,
  spin: 0.24,
  feather: 0.02,
  headWidth: 0.01,
  headR: 1.2,
  headInk: 0.4,
  rBase: 0.75,
  rDepth: 1.6,
} as const;

/** Playground tuning for `searching`: a sphere swept by a camera-facing meridian. */
const SEARCHING = {
  turns: 1,
  tiltAmp: 0.34,
  sphereR: 0.94,
  poleEase: 1.4,
  arms: 13,
  armDepth: 0.72,
  armInk: 0.24,
  scanRate: 0.85,
  scanSwing: 1.05,
  scanWidth: 0.22,
  dimBase: 0.4,
  rBoost: 1.3,
  scanInk: 0.3,
  rBase: 0.5,
  rDepth: 1.4,
} as const;

/** Playground tuning for `waiting`: a barrel of rings breathing in antiphase. */
const WAITING = {
  yawAmp: 0.22,
  yawRate: 0.3,
  tilt: 0.42,
  rings: 9,
  height: 1.5,
  wide: 0.82,
  taper: 0.78,
  breatheRate: 0.75,
  breatheAmp: 0.2,
  spin: 0.16,
  loudR: 0.25,
  loudInk: 0.12,
  rBase: 0.55,
  rDepth: 1.4,
} as const;

/**
 * The still frame for reduced motion, the same for every mode: the end of
 * the morph in, where the mark is fully assembled and seen face-on.
 */
export const ASSEMBLED_AT = CYCLE.dwell + CYCLE.morph;

/**
 * Small-mark tuning. Below `from` px the dots crowd together, so the turning
 * sphere fades its back hemisphere and every dot inks closer to the full
 * tint. It eases in linearly and is full strength at `at` px; large marks are
 * untouched. The radius floor stays modest: legibility comes from ink and
 * spacing, not from fattening every dot.
 */
const SMALL = {
  from: 48,
  at: 18,
  /** Alpha removed from the farthest sphere dots; the mark itself never fades. */
  backFade: 0.75,
  /** Ink shift toward the full tint, on both substrates. */
  inkLift: 0.15,
  /** Radius floor in CSS px. */
  rMin: 0.35,
  /**
   * Alpha kept by working's not-yet-laid thread, so a small mark at the start
   * of its winding is a faint knot rather than an empty slot.
   */
  ghost: 0.22,
} as const;

/** 0 at and above `SMALL.from`, 1 at and below `SMALL.at`. */
export function smallness(size: number): number {
  return clamp01((SMALL.from - size) / (SMALL.from - SMALL.at));
}

/** QDash `--color-primary` per substrate, for themes whose value cannot be resolved. */
const BRAND_FALLBACK: Record<"light" | "dark", Rgb> = {
  light: { r: 0x3d, g: 0x5a, b: 0x99 },
  dark: { r: 0x7f, g: 0x9f, b: 0xdc },
};

// --- geometry ------------------------------------------------------------

/** Deterministic hash in [0, 1). */
function hashD(a: number, b: number): number {
  const h = Math.sin(a * 12.9898 + b * 78.233) * 43758.5453;
  return h - Math.floor(h);
}

/** Value noise on a 2D lattice: smooth, deterministic, cheap. */
function vnoise(x: number, y: number): number {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  let fx = x - xi;
  let fy = y - yi;
  fx = fx * fx * (3 - 2 * fx);
  fy = fy * fy * (3 - 2 * fy);
  const a = hashD(xi, yi);
  const b = hashD(xi + 1, yi);
  const c = hashD(xi, yi + 1);
  const d = hashD(xi + 1, yi + 1);
  return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
}

/** Stable directions on a unit sphere (Fibonacci lattice). */
function fibDir(i: number, n: number): [number, number, number] {
  const golden = Math.PI * (3 - Math.sqrt(5));
  const y = 1 - (2 * (i + 0.5)) / n;
  const rad = Math.sqrt(1 - y * y);
  const a = i * golden;
  return [rad * Math.cos(a), y, rad * Math.sin(a)];
}

/** Shortest signed angular distance, wrapped to (-π, π]. */
function angleDelta(a: number, b: number): number {
  return Math.atan2(Math.sin(a - b), Math.cos(a - b));
}

/** Shared spin + tilt + orthographic projection. */
function makeProj(yaw: number, tilt: number, cx: number, cy: number, scale: number): Projector {
  const st = Math.sin(tilt);
  const ct = Math.cos(tilt);
  const sy = Math.sin(yaw);
  const cyw = Math.cos(yaw);
  return (x, y, z) => {
    const x1 = x * cyw + z * sy;
    const z1 = -x * sy + z * cyw;
    const y1 = y * ct - z1 * st;
    const z2 = y * st + z1 * ct;
    return [cx + x1 * scale, cy - y1 * scale, z2];
  };
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

/** Smootherstep: zero first and second derivative at both ends. */
function smootherE(x: number): number {
  return x * x * x * (x * (x * 6 - 15) + 10);
}

/** easeInOutExpo, the CSS `cubic-bezier(0.87, 0, 0.13, 1)` curve. */
function expoInOut(x: number): number {
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  return x < 0.5 ? 2 ** (20 * x - 10) / 2 : (2 - 2 ** (-20 * x + 10)) / 2;
}

/** The morph curve: smootherstep with a measured amount of expo mixed in. */
function morphEase(x: number, expo: number): number {
  const smooth = smootherE(x);
  return smooth + (expoInOut(x) - smooth) * expo;
}

/** Rotation that cruises: eased at both ends, constant in between, integrating to 1. */
function cruise(x: number, edge: number): number {
  const a = Math.min(0.49, Math.max(0.001, edge));
  const v = 1 / (1 - a);
  if (x <= 0) return 0;
  if (x >= 1) return 1;
  if (x < a) {
    const u = x / a;
    return v * a * (u * u * u - (u * u * u * u) / 2);
  }
  if (x > 1 - a) {
    const u = (1 - x) / a;
    return 1 - v * a * (u * u * u - (u * u * u * u) / 2);
  }
  return v * (a * 0.5 + (x - a));
}

interface Beat {
  /** 0 for the mode's own form, 1 for the mark. */
  m: number;
  /** Turns completed; whole before the mark appears, so it is always face-on. */
  turns: number;
  /** Seconds into the current cycle. */
  local: number;
}

/** Where the shared cycle is at time `t`, for a mode that spins `turns` times. */
function beatAt(t: number, turns: number): Beat {
  const { dwell, morph, settle, expo } = CYCLE;
  const local = t % (dwell + morph * 2);
  const spinSpan = dwell + morph * settle;
  const spun = turns * cruise(Math.min(1, local / spinSpan), 0.22);
  if (local < dwell) return { m: 0, turns: spun, local };
  const intoMorph = local - dwell;
  if (intoMorph < morph) return { m: morphEase(intoMorph / morph, expo), turns: spun, local };
  return { m: morphEase(1 - (intoMorph - morph) / morph, expo), turns: spun, local };
}

/**
 * Which sphere seat each dot flies home from. Pairing by angle means each
 * dot travels roughly radially and the silhouette is legible early.
 */
function seatMap(points: LogoPointSet): Uint32Array {
  const n = points.n;
  const byLogo = new Uint32Array(n);
  const bySeat = new Uint32Array(n);
  const logoAng = new Float32Array(n);
  const seatAng = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    byLogo[i] = i;
    bySeat[i] = i;
    logoAng[i] = Math.atan2(points.p[i * 3 + 1], points.p[i * 3]);
    const [sx, sy] = fibDir(i, n);
    seatAng[i] = Math.atan2(sy, sx);
  }
  byLogo.sort((a, b) => logoAng[a] - logoAng[b]);
  bySeat.sort((a, b) => seatAng[a] - seatAng[b]);
  const seats = new Uint32Array(n);
  for (let k = 0; k < n; k++) seats[byLogo[k]] = bySeat[k];
  return seats;
}

/**
 * Ink by depth, plus a rim term from the baked edge distance so the
 * face-on mark keeps internal structure where depth alone is flat.
 */
function inkOf(zx: number, edge: number): number {
  return INK.inkFar - INK.inkSpan * zx - INK.inkRim * (1 - edge);
}

/** What every mode needs to place its dots in a frame of `size` px. */
interface Stage {
  t: number;
  /** Small-mark strength, see `smallness`. */
  k: number;
  cx: number;
  R: number;
  /** Radius scale: radii were tuned for a 300px frame. */
  rs: number;
}

type ModeFrame = (s: Stage) => Dot[];

const frameThinking: ModeFrame = ({ t, k, cx, R, rs }) => {
  const { p, e, n } = POINTS;
  const o = THINKING;
  const { m, turns } = beatAt(t, o.turns);
  const pt = makeProj(TURN * turns, o.tiltAmp * (1 - m), cx, cx, R);
  const dots: Dot[] = [];
  for (let i = 0; i < n; i++) {
    const [fx, fy, fz] = fibDir(SEATS[i], n);
    // Sphere seats breathe so the dispersed state is alive rather than frozen.
    const wob = o.sphereR * (1 + o.churn * (vnoise(fx * 2 + t * 0.7, fz * 2) - 0.5) * 2);
    let lx = p[i * 3];
    let ly = p[i * 3 + 1];
    let lz = p[i * 3 + 2];
    let halo = 0;
    if (hashD(i, 6.7) < o.haloShare) {
      halo = m;
      const osc = Math.sin(t * o.haloRate + hashD(i, 8.3) * TURN);
      const out = 1 + o.haloOut * (0.5 + 0.5 * osc) * halo;
      lx *= out;
      ly *= out;
      lz += o.haloZ * osc * halo;
    }
    const [px, py, z] = pt(
      fx * wob + (lx - fx * wob) * m,
      fy * wob + (ly - fy * wob) * m,
      fz * wob + (lz - fz * wob) * m,
    );
    const zx = clamp01((z + 1) / 2);
    // Back-face fade belongs to the sphere only, so the assembled mark stays whole.
    const back = SMALL.backFade * k * (1 - m) * (1 - zx);
    dots.push({
      x: px,
      y: py,
      z,
      r: (o.rBase + o.rDepth * zx + o.haloR * halo) * rs,
      white: inkOf(zx, e[i] * m + (1 - m)),
      a: (1 - o.flightFade * Math.sin(Math.PI * m)) * (1 - back),
    });
  }
  return dots;
};

/**
 * The thread does not exist until its bright head has laid it: it winds
 * across the dwell, holds while the mark shows, and unwinds on the way back.
 */
const frameWorking: ModeFrame = ({ t, k, cx, R, rs }) => {
  const { p, e, n } = POINTS;
  const o = WORKING;
  const { m, local } = beatAt(t, 0);
  const c = 1 - m;
  const pt = makeProj(o.lean + o.yawAmp * Math.sin(t * o.yawRate) * c, o.tilt * c, cx, cx, R);
  const into = local - CYCLE.dwell;
  const prog =
    local < CYCLE.dwell
      ? local / CYCLE.dwell
      : into < CYCLE.morph
        ? 1
        : clamp01(1 - (into - CYCLE.morph) / CYCLE.morph);
  const head = prog * n;
  const feather = Math.max(1, n * o.feather);
  const headW = Math.max(1, n * o.headWidth);
  const winding = local < CYCLE.dwell;
  const ca = Math.cos(t * o.spin);
  const sa = Math.sin(t * o.spin);
  const dots: Dot[] = [];
  for (let i = 0; i < n; i++) {
    const seat = SEATS[i];
    // A (p, q) torus knot: coprime windings keep it one closed curve.
    const u = (seat / n) * TURN;
    const ring = o.major + o.minor * Math.cos(o.knotTurns * u);
    const kx = ring * Math.cos(o.wraps * u);
    const ky = o.minor * Math.sin(o.knotTurns * u);
    const kz = ring * Math.sin(o.wraps * u);
    const bx = kx * ca + kz * sa;
    const bz = -kx * sa + kz * ca;
    const lx = p[i * 3];
    const ly = p[i * 3 + 1];
    const lz = p[i * 3 + 2];
    const [px, py, z] = pt(lx + (bx - lx) * c, ly + (ky - ly) * c, lz + (bz - lz) * c);
    const zx = clamp01((z + 1) / 2);
    const laid = clamp01((head - seat) / feather);
    const at = winding ? Math.exp(-(((seat - head) / headW) ** 2)) : 0;
    dots.push({
      x: px,
      y: py,
      z,
      r: (o.rBase + o.rDepth * zx + o.headR * at * c) * rs,
      white: inkOf(zx, e[i] * m + (1 - m)) - o.headInk * at * c,
      // Present once laid, absent (a ghost when small) ahead of the head, never
      // partial in the mark.
      a: 1 - (1 - Math.max(laid, SMALL.ghost * k)) * c,
    });
  }
  return dots;
};

/**
 * A lit meridian sweeps the near side of the sphere, anchored to the camera
 * so it never wanders behind; the lattice's own spiral arms are inked in
 * three weights so the surface reads as a weave being examined.
 */
const frameSearching: ModeFrame = ({ t, cx, R, rs }) => {
  const { p, e, n } = POINTS;
  const o = SEARCHING;
  const { m, turns } = beatAt(t, o.turns);
  const g = 1 - m;
  const yaw = TURN * turns;
  const pt = makeProj(yaw, o.tiltAmp * g, cx, cx, R);
  const scan = yaw + Math.PI / 2 + o.scanSwing * Math.sin(t * o.scanRate);
  const dots: Dot[] = [];
  for (let i = 0; i < n; i++) {
    const seat = SEATS[i];
    const [ax, ay, az] = fibDir(seat, n);
    // Compress latitude toward the equator so the foreshortened caps stay airy.
    const lat = (ay < 0 ? -1 : 1) * Math.abs(ay) ** o.poleEase;
    const ring0 = Math.sqrt(Math.max(1e-9, 1 - ay * ay));
    const ring = Math.sqrt(Math.max(0, 1 - lat * lat)) / ring0;
    const fx = ax * ring;
    const fz = az * ring;
    const tier = (seat % o.arms) % 3;
    const arm = 1 - o.armDepth * (tier === 0 ? 0 : tier === 1 ? 0.5 : 1);
    const lx = p[i * 3];
    const ly = p[i * 3 + 1];
    const lz = p[i * 3 + 2];
    const [px, py, z] = pt(
      lx + (fx * o.sphereR - lx) * g,
      ly + (lat * o.sphereR - ly) * g,
      lz + (fz * o.sphereR - lz) * g,
    );
    const d = angleDelta(Math.atan2(fz, fx), scan);
    const boost = Math.exp(-(d * d) / o.scanWidth) * g;
    const zx = clamp01((z + 1) / 2);
    dots.push({
      x: px,
      y: py,
      z,
      r: (o.rBase + o.rDepth * zx * arm + o.rBoost * boost) * rs,
      white: inkOf(zx, e[i] * m + (1 - m)) + o.armInk * (1 - arm) * g - o.scanInk * boost,
      // Unswept dots dim only once the sphere has formed; the mark is never partial.
      a: 1 - (1 - o.dimBase) * g * (1 - Math.min(1, boost)),
    });
  }
  return dots;
};

/**
 * A barrel of stacked rings, held at a tilt so the layering shows, that
 * draws tall and narrow then settles short and wide: height and radius move
 * in antiphase, so it reads as breathing rather than zooming.
 */
const frameWaiting: ModeFrame = ({ t, cx, R, rs }) => {
  const { p, e, n } = POINTS;
  const o = WAITING;
  const { m } = beatAt(t, 0);
  const c = 1 - m;
  const pt = makeProj(o.yawAmp * Math.sin(t * o.yawRate) * c, o.tilt * c, cx, cx, R);
  const perRing = Math.ceil(n / o.rings);
  const breath = Math.sin(t * o.breatheRate);
  const height = o.height * (1 + o.breatheAmp * breath);
  const wide = o.wide * (1 - o.breatheAmp * 0.72 * breath);
  const spin = t * o.spin;
  const dots: Dot[] = [];
  for (let i = 0; i < n; i++) {
    const seat = SEATS[i];
    const u = (seat % o.rings) / (o.rings - 1) - 0.5;
    const taper = Math.cos(u * Math.PI * o.taper);
    const ang = (Math.floor(seat / o.rings) / perRing) * TURN + spin;
    const bx = Math.cos(ang) * wide * taper;
    const by = u * height;
    const bz = Math.sin(ang) * wide * taper;
    const lx = p[i * 3];
    const ly = p[i * 3 + 1];
    const lz = p[i * 3 + 2];
    const [px, py, z] = pt(lx + (bx - lx) * c, ly + (by - ly) * c, lz + (bz - lz) * c);
    const zx = clamp01((z + 1) / 2);
    // The widest rings read brightest, so the exhale is carried by ink too.
    const loud = clamp01(taper);
    dots.push({
      x: px,
      y: py,
      z,
      r: (o.rBase + o.rDepth * zx + o.loudR * loud * c) * rs,
      white: inkOf(zx, e[i] * m + (1 - m)) - o.loudInk * loud * c,
      a: 1,
    });
  }
  return dots;
};

const FRAMES: Record<ActivityLogoMode, ModeFrame> = {
  thinking: frameThinking,
  working: frameWorking,
  searching: frameSearching,
  waiting: frameWaiting,
};

/** One instant of a mode as z-sorted, radius-clamped dots in draw order. */
export function logoFrame(size: number, t: number, mode: ActivityLogoMode = "thinking"): Dot[] {
  const k = smallness(size);
  const rMin = INK.rMin + (SMALL.rMin - INK.rMin) * k;
  const raw = FRAMES[mode]({
    t,
    k,
    cx: size / 2,
    R: (size / 2) * 0.82,
    rs: (size / 300) ** INK.rsPow,
  });
  const dots: Dot[] = [];
  for (const d of raw) {
    if (d.a < 0.02) continue;
    d.r = Math.max(rMin, d.r);
    d.white -= SMALL.inkLift * k;
    dots.push(d);
  }
  dots.sort((d1, d2) => d1.z - d2.z);
  return dots;
}

// --- brand tint ----------------------------------------------------------

/** Relative luminance in [0, 1], sRGB weights, no gamma. */
function luminance(c: Rgb): number {
  return (0.2126 * c.r + 0.7152 * c.g + 0.0722 * c.b) / 255;
}

/**
 * Pull a brand colour far enough off the substrate to stay visible: lighten
 * a dark tint on dark themes, darken a pale one on light themes. Hue is kept.
 */
export function adaptTint(tint: Rgb, dark: boolean): Rgb {
  const l = luminance(tint);
  if (dark && l < 0.42) {
    const f = (0.42 - l) / (1 - l);
    return {
      r: Math.round(tint.r + (255 - tint.r) * f),
      g: Math.round(tint.g + (255 - tint.g) * f),
      b: Math.round(tint.b + (255 - tint.b) * f),
    };
  }
  if (!dark && l > 0.62) {
    const f = (l - 0.62) / l;
    return {
      r: Math.round(tint.r * (1 - f)),
      g: Math.round(tint.g * (1 - f)),
      b: Math.round(tint.b * (1 - f)),
    };
  }
  return tint;
}

/**
 * Colour for one dot. The ink value stays the depth cue: it sets where the
 * dot sits on a ramp from the substrate to the brand colour, so far dots
 * recede toward the background and near dots carry the full tint.
 */
export function tintedInk(tint: Rgb, white: number, dark: boolean, alpha: number): string {
  const w = clamp01(white);
  const v = dark ? 1 - w : w;
  const mix = (c: number) => Math.round(dark ? c * v : 255 + (c - 255) * (1 - v));
  return `rgba(${mix(tint.r)},${mix(tint.g)},${mix(tint.b)},${alpha})`;
}

/** Parse `#rgb`, `#rrggbb`, or `rgb()`/`rgba()`; null for anything else. */
function parseColor(value: string): Rgb | null {
  const s = value.trim();
  const hex = /^#([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(s)?.[1];
  if (hex) {
    const full = hex.length === 3 ? hex.replace(/./g, (c) => c + c) : hex;
    const n = Number.parseInt(full, 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  const rgb = /^rgba?\(\s*(\d+)[\s,]+(\d+)[\s,]+(\d+)/i.exec(s);
  if (rgb) return { r: Number(rgb[1]), g: Number(rgb[2]), b: Number(rgb[3]) };
  return null;
}

/**
 * The active theme's `--color-primary` as RGB. Hex and rgb() values parse
 * directly; any other syntax (built-in themes use oklch) is converted by
 * painting one pixel. Falls back to the QDash brand colour for the substrate.
 */
export function resolveBrandTint(el: Element, dark: boolean): Rgb {
  const raw = getComputedStyle(el).getPropertyValue("--color-primary").trim();
  let tint = raw ? parseColor(raw) : null;
  if (!tint && raw) {
    const probe = document.createElement("canvas");
    probe.width = 1;
    probe.height = 1;
    const ctx = probe.getContext("2d", { willReadFrequently: true });
    if (ctx) {
      ctx.fillStyle = raw;
      ctx.fillRect(0, 0, 1, 1);
      const [r, g, b, a] = ctx.getImageData(0, 0, 1, 1).data;
      if (a > 0) tint = { r, g, b };
    }
  }
  return adaptTint(tint ?? BRAND_FALLBACK[dark ? "dark" : "light"], dark);
}

function paintDots(ctx: CanvasRenderingContext2D, dots: Dot[], dark: boolean, tint: Rgb): void {
  for (const d of dots) {
    ctx.fillStyle = tintedInk(tint, d.white, dark, d.a);
    ctx.beginPath();
    ctx.arc(d.x, d.y, d.r, 0, TURN);
    ctx.fill();
  }
}

// --- component -----------------------------------------------------------

function usePrefersReducedMotion(): boolean {
  // Read up front so a reduced-motion user never gets one animated pass first.
  const [reduced, setReduced] = useState(
    () =>
      typeof window !== "undefined" &&
      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches === true,
  );
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener?.("change", update);
    return () => query.removeEventListener?.("change", update);
  }, []);
  return reduced;
}

/** The default mark size: the height of a `text-sm` line, so a row never grows. */
const ACTIVITY_LOGO_SIZE = 20;

/**
 * The OQTOPUS mark animating what the assistant is doing, tinted with the
 * theme's primary colour. Decorative: the label next to it says what is
 * happening. Reduced motion shows the assembled mark as one still frame in
 * every mode, and the loop pauses while the canvas is offscreen or the tab
 * is hidden.
 */
export function ActivityLogo({
  mode = "thinking",
  size = ACTIVITY_LOGO_SIZE,
  className,
}: {
  mode?: ActivityLogoMode;
  size?: number;
  className?: string;
}) {
  const ref = useRef<HTMLCanvasElement | null>(null);
  const dark = useIsDarkTheme();
  const theme = useThemeName();
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    canvas.width = Math.round(size * dpr);
    canvas.height = Math.round(size * dpr);
    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    // Re-read on theme change: the effect depends on the theme name.
    const tint = resolveBrandTint(canvas, dark);

    const render = (t: number, frameMode: ActivityLogoMode) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, size, size);
      paintDots(ctx, logoFrame(size, t, frameMode), dark, tint);
    };

    if (reduced) {
      // One still for every mode: the face-on mark (working's own ends leaned).
      render(ASSEMBLED_AT, "thinking");
      return;
    }

    let raf = 0;
    let running = false;
    // Wall-clock time keeps every instance in phase, so the mark does not jump
    // when the live activity moves between rows or changes mode.
    const loop = () => {
      render(performance.now() / 1000, mode);
      if (running) raf = requestAnimationFrame(loop);
    };
    const start = () => {
      if (running) return;
      running = true;
      raf = requestAnimationFrame(loop);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    render(performance.now() / 1000, mode);

    let visible = true;
    const io =
      typeof IntersectionObserver === "undefined"
        ? null
        : new IntersectionObserver(([entry]) => {
            visible = entry.isIntersecting;
            if (visible && document.visibilityState !== "hidden") start();
            else stop();
          });
    io?.observe(canvas);
    const onVisibility = () => {
      if (document.visibilityState === "hidden") stop();
      else if (visible) start();
    };
    document.addEventListener("visibilitychange", onVisibility);
    if (!io && document.visibilityState !== "hidden") start();

    return () => {
      stop();
      io?.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [size, dark, theme, reduced, mode]);

  return (
    <canvas
      ref={ref}
      aria-hidden="true"
      className={className}
      style={{ width: size, height: size, display: "block", flexShrink: 0 }}
      data-testid="activity-logo"
      data-mode={mode}
      data-motion={reduced ? "still" : "animated"}
    />
  );
}

